[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path -Parent $PSScriptRoot
$skillSource = Join-Path $repoRoot 'skills\sports-science-research-grounding'
$skillTargets = @(
    (Join-Path $env:USERPROFILE '.agents\skills\sports-science-research-grounding'),
    (Join-Path $env:USERPROFILE '.codex\skills\sports-science-research-grounding'),
    (Join-Path $env:USERPROFILE '.claude\skills\sports-science-research-grounding'),
    (Join-Path $env:USERPROFILE '.gemini\skills\sports-science-research-grounding')
)

foreach ($target in $skillTargets) {
    New-Item -ItemType Directory -Path $target -Force | Out-Null
    Copy-Item -Path (Join-Path $skillSource '*') -Destination $target -Recurse -Force
}

$mcpConfigPath = Join-Path $env:USERPROFILE '.gemini\config\mcp_config.json'
$mcpConfigDirectory = Split-Path -Parent $mcpConfigPath
New-Item -ItemType Directory -Path $mcpConfigDirectory -Force | Out-Null
if (Test-Path -LiteralPath $mcpConfigPath) {
    $mcpConfig = Get-Content -LiteralPath $mcpConfigPath -Raw | ConvertFrom-Json
} else {
    $mcpConfig = [pscustomobject]@{ mcpServers = [pscustomobject]@{} }
}
if (-not $mcpConfig.mcpServers) {
    $mcpConfig | Add-Member -NotePropertyName mcpServers -NotePropertyValue ([pscustomobject]@{}) -Force
}
$mcpExecutable = Join-Path $repoRoot '.venv\Scripts\zotero-bridge-mcp.exe'
